using System.Security.Cryptography;
using StarPlayer.SimHarness.Evidence;

namespace StarPlayer.SimHarness.Tests.Evidence;

/// <summary>
/// B1-T10 document Golden: FROZEN TEST_ONLY inputs (tests/Fixtures/b1-golden, exported once from the TEST_ONLY world and never regenerated by a normal run) and expected payload bytes / SHA / A+ written by
/// an INDEPENDENT Python implementation (tools/b1-golden/golden.py). The production code must reproduce them; it is not its own oracle. The Calibration set is a real-engine run of 12 games per stratum that ends SEEDS_EXHAUSTED under the 100,000-PA target.
/// </summary>
public class GoldenTests
{
    private static readonly string Dir = Path.Combine(H.Root, "tests", "Fixtures", "b1-golden");

    private static readonly JObject Expected = (JObject)StrictJson.Parse(File.ReadAllBytes(Path.Combine(Dir, "expected.json")));

    private static string Sha(byte[] b) => Convert.ToHexString(SHA256.HashData(b)).ToLowerInvariant();

    private static JObject E(string path) => (JObject)path.Split('/').Aggregate((JNode)Expected, (n, k) => ((JObject)n)[k]);

    private static (JObject Doc, List<JObject> Units, JObject? Pzl6) Load(string folder, string set, EvidenceKind kind)
    {
        var raw = (JObject)E($"{set}/raw_sha256");
        JObject Read(string name)
        {
            var bytes = File.ReadAllBytes(Path.Combine(Dir, folder, name));
            Assert.Equal(Schema.Text(raw[name]), Sha(bytes));                               // the frozen input is the one the Golden was computed from
            return (JObject)StrictJson.Parse(bytes);
        }

        var doc = Read("document.json");
        EvidenceRules.Validate(kind, Jcs.Bytes(doc));
        var units = raw.Members.Select(m => m.Key).Where(k => k.StartsWith("unit-", StringComparison.Ordinal)).Order(StringComparer.Ordinal).Select(Read).ToList();
        units.ForEach(u => EvidenceRules.Validate(EvidenceKind.UnitPzl, Jcs.Bytes(u)));
        var pzl6 = raw.Has("pzl6.json") ? Read("pzl6.json") : null;
        if (pzl6 is not null)
            EvidenceRules.Validate(EvidenceKind.Pzl6, Jcs.Bytes(pzl6));
        return (doc, units, pzl6);
    }

    private static void Same(string set, EvidencePayload p)
    {
        Assert.Equal(Schema.Long(E(set)["payload_bytes"]), p.Canonical.Length);
        Assert.Equal(Schema.Text(E(set)["payload_sha256"]), Sha(p.Canonical));
        Assert.Equal(Schema.Text(E(set)["a_plus"]), p.Hash);
    }

    [Fact]
    public void The_dominance_payload_bytes_and_a_plus_equal_the_independent_golden()
    {
        var (doc, units, _) = Load("dom", "dominance", EvidenceKind.Dominance);
        Same("dominance", EvidenceHash.Dominance(doc, units));
    }

    [Fact]
    public void The_integration_payload_bytes_and_a_plus_equal_the_independent_golden()
    {
        var (doc, units, pzl6) = Load("int", "integration", EvidenceKind.Family);
        Same("integration", EvidenceHash.Family(doc, units, pzl6));
    }

    [Fact]
    public void The_calibration_payload_bytes_and_a_plus_equal_the_independent_golden()
    {
        var (doc, units, _) = Load("cal", "calibration", EvidenceKind.Family);
        Same("calibration", EvidenceHash.Family(doc, units, null));
    }

    [Fact]
    public void The_phase_payload_over_the_three_real_children_equals_the_independent_golden_and_gv_c02_is_confirmed_by_a_second_implementation()
    {
        var (cd, cu, _) = Load("cal", "calibration", EvidenceKind.Family);
        var (id, iu, ip) = Load("int", "integration", EvidenceKind.Family);
        var (dd, du, _) = Load("dom", "dominance", EvidenceKind.Dominance);
        var input = (JObject)StrictJson.Parse(File.ReadAllBytes(Path.Combine(Dir, "phase-input.json")));
        var phase = EvidenceHash.Phase(EvidenceHash.Family(cd, cu, null), EvidenceHash.Family(id, iu, ip), EvidenceHash.Dominance(dd, du), Schema.Items(input["checks"]).Select(Schema.Obj).ToList());
        Same("phase", phase);

        // GV-C02's DOMINANCE / PHASE digests were computed once (S00.5 §7); the C# implementation now agrees with the Python run
        var c02 = Jcs.Bytes(J.O(("max", J.S(Jcs.Es(double.MaxValue))), ("min", J.S(Jcs.Es(double.Epsilon))), ("negative_zero", J.S(Jcs.Es(-0.0)))));
        Assert.Equal(Schema.Text(E("gv_c02")["dominance"]), EvidenceHash.APlus(EvidenceHash.DominancePrefix, c02));
        Assert.Equal(Schema.Text(E("gv_c02")["phase"]), EvidenceHash.APlus(EvidenceHash.PhasePrefix, c02));
        Assert.Equal("sha256:e581ac6c69c0d5d877f4ced827e51a373c63ac412d301eeb1083c4c154700c24", EvidenceHash.APlus(EvidenceHash.DominancePrefix, c02));
    }
}